import React, { Component } from "react";
import {
  Layout,
  Breadcrumb,
  Table,
  Card,
  Button,
  Select,
  message,
  Modal,
  Spin,
} from "antd";
import Sidebar2 from "./common/Sidebar2";
import Navbar from "./common/Navbar";
import BottomBar from "./common/BottomBar";
import Bridge from "../constants/Bridge";
import Apis from "../constants/Apis";
import { CopyOutlined } from "@ant-design/icons";
import InstitutionalReferralEdit from "./InstitutionalReferralEdit";
const { Option } = Select;
const { Content } = Layout;

class InstitutionalReferralView extends Component {
  constructor(props) {
    super(props);
    this.state = {
      loading: false,
      name: "",
      email: "",
      mobile: "",
      accordance: "",
      totalInvestedAmount: "",
      facebook: "",
      instagram: "",
      linkedIn: "",
      twitter: "",
      accountNo: "",
      ifsc_code: "",
      bankname: "",
      profileImg: "",
      referralCode: "",
      referralLink: "",
      showEdit: false,
      showProfileTbl: true,
      referralList: [],
      user_list: [],
      show_list_of_investment: false,
      investor_details_investment: [],
      investment_list_loading: false,
    };
    this.hideEditModal = this.hideEditModal.bind(this);
    this.updateEditModal = this.updateEditModal.bind(this);
  }

  componentDidMount() {
    this.getlist();
  }

  get_user_list = () => {
    let params = {
      reffered_by: this.state.referralCode,
    };
    // console.log("params", params);
    Bridge.admin.get_institutional_investor_list(params).then((result) => {
